// Общие шаги для тестов скриншотов системы на лендинге (#99cf43b7, план specs/landing.md). Гость, только чтение.
// Лендинг — https://techory.ai (не app.techory.ai), адрес абсолютный.
import { expect, Locator, Page } from '@playwright/test';

export const LANDING_URL = 'https://techory.ai/';

/** Новые скриншоты (commit ccbfb0c). Переснимут под другими именами — обновить здесь. */
export const PRODUCT_IMAGES = [
  'techory-schedule.png',
  'techory-dashboard.png',
  'techory-pricebook.png',
  'techory-assistant-card.png',
];

/** Логотип Techory в шапке и подвале (не скриншот системы). */
export const LOGO_SRC = /\/def5874c9_[^/]+\.png$/;

export const productImages = (page: Page): Locator => page.locator('img[src*="/product/"]');

/** Открыть лендинг и дождаться, пока на странице появятся 4 скриншота. */
export async function openLanding(page: Page) {
  await page.goto(LANDING_URL);
  await expect(productImages(page)).toHaveCount(PRODUCT_IMAGES.length);
}

/** Прокрутить к картинке (loading=lazy) и дождаться загрузки: naturalWidth > 0. */
export async function scrollAndWaitLoaded(img: Locator) {
  await img.scrollIntoViewIfNeeded();
  await expect
    .poll(() => img.evaluate((e: HTMLImageElement) => (e.complete ? e.naturalWidth : 0)), { message: 'картинка не загрузилась' })
    .toBeGreaterThan(0);
}

/** Имя файла из адреса картинки. */
export const fileName = (src: string) => new URL(src).pathname.split('/').pop() || '';
